import math

def attained(v):
    # v is in range iff some integer n has x = n^2 - v with floor(x) = n
    # for |n| > 50 and |v| < 2500, x = n^2 - v is far from [n, n+1) only when n^2 is large; bound is safe
    for n in range(-100, 101):
